const EMPTY_STATE=()=>({owned:[],wishlist:[],requests:[],listings:[],reviews:{}});
let state;try{state={...EMPTY_STATE(),...JSON.parse(localStorage.getItem(CONFIG.storageKey)||'{}')};for(const k of ['owned','wishlist','requests','listings'])if(!Array.isArray(state[k]))state[k]=[];}catch{state=EMPTY_STATE();}
let filters={category:'ทั้งหมด',query:'',sort:'featured',format:'ทั้งหมด',price:'all',saved:false};
let studioSeller='studio',studioTab='requests',toastTimer;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'฿'+Number(n).toLocaleString('th-TH');
const allProducts=()=>[...PRODUCTS,...state.listings];
const product=id=>allProducts().find(p=>p.id===id);
const owns=id=>state.owned.some(o=>o.productId===id);
const seller=id=>SELLERS[id]||SELLERS.studio;
