function persist(){try{localStorage.setItem(CONFIG.storageKey,JSON.stringify(state));}catch{toast('บันทึกถาวรไม่ได้: พื้นที่จัดเก็บเบราว์เซอร์ไม่พร้อมใช้งาน');}updateCounts();}
function updateCounts(){$('#owned-count').textContent=state.owned.length;$('#wish-count').textContent=state.wishlist.length;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),3500);}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function go(page){closeModal();if(location.hash==='#'+page)render();else location.hash=page;window.scrollTo({top:0});}
const bars=()=>'<div class="mini-chart">'+[38,61,45,78,58,93,74,100].map(n=>`<i style="height:${n}%"></i>`).join('')+'</div>';
function cover(p,interactive=true){let inside=p.style==='sheet'?`<div class="sheet-preview"><div class="sheet-title">${esc(p.preview)}</div><div class="sheet-sub">A LITTLE STRUCTURE. A LOT MORE CLARITY.</div><table aria-hidden="true"><tr><td>Overview</td><td>Plan</td><td>Actual</td></tr><tr><td>This month</td><td>12,500</td><td>14,250</td></tr><tr><td>Progress</td><td>75%</td><td>82%</td></tr></table>${bars()}</div>`:p.style==='planner'?`<div class="planner-preview"><small>THE EVERYDAY COLLECTION</small><strong>${esc(p.preview).replace(/\n/g,'<br>')}</strong><div class="planner-lines"></div></div>`:`<div class="prompt-preview"><small>WORKROOM / THE AI TOOLKIT</small><strong>${esc(p.preview).replace(/\n/g,'<br>')}</strong><code>→ ideas into action_</code></div>`;
if(PREVIEW_IMAGES[p.id])inside=`<img class="workbook-preview" src="${PREVIEW_IMAGES[p.id]}" alt="ตัวอย่าง ${esc(p.title)} พร้อมตาราง สูตร และกราฟจากข้อมูลสมมติ" width="1100" height="720">`;
return `<div class="cover ${esc(p.tone)}"><span class="label">${esc(p.tag)}</span>${interactive?`<button class="save ${state.wishlist.includes(p.id)?'saved':''}" data-action="save" data-id="${esc(p.id)}" aria-label="บันทึก ${esc(p.title)}" aria-pressed="${state.wishlist.includes(p.id)}">${state.wishlist.includes(p.id)?'♥':'♡'}</button><button class="cover-button" data-action="detail" data-id="${esc(p.id)}" aria-label="ดู ${esc(p.title)}">${inside}</button>`:inside}</div>`;}
function card(p){const s=seller(p.seller);return `<article class="product">${cover(p)}<div class="product-meta">${esc(p.category)} <span>·</span> ${esc(p.format)}</div><h3><button data-action="detail" data-id="${esc(p.id)}">${esc(p.title)}</button></h3><p>${esc(p.desc)}</p><div class="card-bottom"><button class="creator" data-action="seller" data-id="${esc(p.seller)}"><span class="avatar">${s.initials}</span>${s.name}</button><span class="rating">★ ${esc(p.rating)}</span><span class="price">${money(p.price)}</span></div></article>`;}
function empty(title,text,button='เลือกดูสินค้า',action='market'){return `<div class="empty"><span class="empty-icon">✳</span><h3>${title}</h3><p>${text}</p><button class="btn" data-action="${action}">${button} ↗</button></div>`;}
function render(){updateCounts();let page=location.hash.slice(1)||'market';if(!['market','library','requests','studio'].includes(page))page='market';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#main').innerHTML=page==='market'?market():page==='library'?library():page==='requests'?requests():studio();if(page==='market')renderGrid();}
function market(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">MODU / MODIFIED BY YOU</div><h1>Ready to use.<br><em>Yours to modify.</em></h1><p>เครื่องมือดิจิทัลพร้อมใช้ ที่ช่วยให้ชีวิตและงานง่ายขึ้น<br>เลือกสิ่งที่ใช่ แล้วปรับให้เป็นของคุณ</p><form class="searchbox" id="search-form"><span aria-hidden="true">⌕</span><input id="search-input" aria-label="ค้นหาสินค้า" placeholder="วันนี้อยากให้อะไรง่ายขึ้น?" value="${esc(filters.query)}"><button class="btn small" type="submit">ค้นหา ↗</button></form><div class="popular">ค้นหาบ่อย <button data-action="search" data-query="ต้นทุน">ต้นทุนร้านค้า</button><button data-action="search" data-query="planner">Planner</button><button data-action="search" data-query="Prompt">AI Prompt</button></div></div><div class="hero-art" aria-label="ตัวอย่างหน้าจอเครื่องมือจัดการร้าน"><span class="quality-label">✓ Curated for real life</span><div class="art-window workbook-hero"><img src="${PREVIEW_IMAGES.cost}" alt="ภาพตัวอย่าง Excel สรุปยอดขายร้านค้า ตารางต้นทุนและกราฟรายเดือน ข้อมูลสมมติ" width="1100" height="720"></div><div class="floating-note"><span>MODIFIED BY YOU</span><strong>Your workflow. Your way. ↗</strong><p>ซื้อแล้ว ขอปรับให้ตรงงานได้</p></div></div></section><div class="trust-row"><span><b>⊞</b> พร้อมเริ่มใช้ มีตัวอย่างประกอบ</span><span><b>✓</b> รายละเอียดและขอบเขตชัดเจน</span><span><b>↗</b> ขอปรับแต่งกับผู้สร้างโดยตรง</span><span><b>↧</b> ซื้อแล้วเข้าถึงได้ในสินค้าของฉัน</span></div><section class="catalog" id="catalog"><div class="section-head"><div><h2>Find your everyday upgrade.</h2><p>เครื่องมือเล็ก ๆ ที่สร้างความต่างให้วันของคุณ</p></div><button class="text-link" data-action="how">ซื้อและใช้งานอย่างไร ↗</button></div><div class="filter-row"><div class="chips">${CATEGORIES.map(c=>`<button class="chip ${filters.category===c?'active':''}" data-action="category" data-id="${esc(c)}">${c}</button>`).join('')}</div><select id="sort" aria-label="เรียงสินค้า"><option value="featured">เรียงตาม: แนะนำ</option><option value="low">ราคา: น้อยไปมาก</option><option value="high">ราคา: มากไปน้อย</option><option value="rating">คะแนนรีวิว</option></select></div><div class="results-note"><span id="result-count"></span><div class="price-range"><select id="format" aria-label="ประเภทไฟล์">${['ทั้งหมด','Excel','Google Sheets','Notion','PDF','Prompt'].map(f=>`<option ${filters.format===f?'selected':''}>${f}</option>`).join('')}</select><select id="price-filter" aria-label="ช่วงราคา"><option value="all">ทุกช่วงราคา</option><option value="300">ไม่เกิน ฿300</option><option value="500">ไม่เกิน ฿500</option></select><button class="text-link" data-action="clear">ล้างตัวกรอง</button></div></div><div class="grid" id="product-grid"></div></section><section class="custom-banner"><div><div class="eyebrow">GOOD START. PERFECT FIT.</div><h2>ชอบเครื่องมือนี้<br>แต่อยากให้เป็นแบบของคุณ?</h2><p>เริ่มจากสินค้าที่ซื้อ แล้วส่งบรีฟให้ผู้สร้างคนเดิม<br>เพิ่มฟังก์ชัน เปลี่ยนรูปแบบ หรือปรับให้เข้ากับงานของคุณ</p><button class="btn light" data-action="custom-start">ลองส่งคำขอปรับแต่ง ↗</button><div class="custom-steps"><span><b>01</b> เลือกสินค้าที่ซื้อ</span><span>→</span><span><b>02</b> ส่งบรีฟ</span><span>→</span><span><b>03</b> รับข้อเสนอ</span></div></div><div class="brief-card"><h3>Make it yours. <span style="float:right">↗</span></h3><p>ถึง Everyday Studio · ตัวอย่างคำขอ</p><strong>เพิ่ม Dashboard แยกยอดขาย 2 สาขา</strong><p>อยากดูยอดขายรายวันและเปรียบเทียบต้นทุน<br>โดยใช้ไฟล์ Small Shop Finance Kit เดิม</p><div class="badge">งบประมาณ ฿1,500 – ฿3,000</div></div></section><div class="section-head"><div><h2>Thoughtfully made. Ready for you.</h2><p>จากไอเดียของผู้สร้าง สู่เครื่องมือที่ใช้ได้ในทุกวัน</p></div></div><div class="how-grid"><div><span class="step">01 /</span><strong>เห็นก่อนว่าได้อะไร</strong><p>ดูตัวอย่าง ขอบเขต และโปรแกรมที่รองรับก่อนตัดสินใจ</p></div><div><span class="step">02 /</span><strong>เริ่มจากสิ่งที่พร้อมใช้</strong><p>รับเครื่องมือพร้อมข้อมูลตัวอย่างและวิธีเริ่มต้น</p></div><div><span class="step">03 /</span><strong>เติบโตไปกับงานของคุณ</strong><p>ขอให้ผู้สร้างปรับแต่งเพิ่มเติมเมื่อความต้องการเปลี่ยนไป</p></div></div>`;}
function renderGrid(){let items=allProducts().filter(p=>(filters.category==='ทั้งหมด'||p.category===filters.category)&&(filters.format==='ทั้งหมด'||p.format===filters.format)&&(filters.price==='all'||p.price<=Number(filters.price))&&(!filters.saved||state.wishlist.includes(p.id))&&(`${p.title} ${p.thai} ${p.desc} ${p.category} ${p.format}`.toLowerCase().includes(filters.query.toLowerCase())));if(filters.sort==='low')items.sort((a,b)=>a.price-b.price);if(filters.sort==='high')items.sort((a,b)=>b.price-a.price);if(filters.sort==='rating')items.sort((a,b)=>Number(b.rating)-Number(a.rating));$('#product-grid').innerHTML=items.length?items.map(card).join(''):empty('ยังไม่พบสินค้าที่ตรงกัน','ลองเปลี่ยนคำค้นหรือเลือกหมวดอื่น','ล้างตัวกรอง','clear');$('#result-count').textContent=`${items.length} เครื่องมือ${filters.saved?' · รายการที่บันทึก':''}${filters.query?' · “'+filters.query+'”':''}`;$('#sort').value=filters.sort;$('#price-filter').value=filters.price;document.querySelectorAll('[data-action="category"]').forEach(b=>b.classList.toggle('active',b.dataset.id===filters.category));}
function detail(id){const p=product(id);if(!p)return;const s=seller(p.seller);modal(`<div class="detail-grid"><div>${cover(p,false)}<div class="note">ภาพและคะแนนรีวิวเป็นข้อมูลตัวอย่างใน Prototype</div><button class="btn light full" data-action="preview" data-id="${id}">เปิดตัวอย่างการใช้งาน ↗</button></div><div><div class="eyebrow">${esc(p.category)} / ${esc(p.format)}</div><h2 id="modal-title">${esc(p.title)}</h2><p>${esc(p.thai)}</p><button class="creator" data-action="seller" data-id="${p.seller}"><span class="avatar">${s.initials}</span>โดย ${s.name} ↗</button><p style="margin-top:16px">★ ${esc(p.rating)} · ${p.reviews} รีวิวตัวอย่าง</p><div class="price">${money(p.price)} <small style="font-size:11px;font-weight:400">ซื้อครั้งเดียว</small></div><button class="btn full" data-action="${owns(id)?'custom':'checkout'}" data-id="${id}">${owns(id)?'ซื้อแล้ว · ขอปรับแต่งกับผู้ขาย ↗':'ทดลองซื้อสินค้านี้ ↗'}</button>${owns(id)?`<button class="btn light full" style="margin-top:9px" data-action="download" data-id="${id}">ดาวน์โหลดไฟล์สาธิต ↧</button>`:''}<p style="font-size:10px;margin-top:10px">ไม่มีการเรียกเก็บเงินจริง · ใช้ข้อมูลในเบราว์เซอร์นี้</p></div></div><div class="detail-info details-columns"><div><h3>สิ่งที่มีในสินค้าตัวอย่างนี้</h3><ul>${p.includes.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><h3>โปรแกรมที่รองรับ</h3><p>${esc(p.compat)}</p></div><div><h3>ปรับแต่งอะไรได้บ้าง?</h3><p>${esc(p.custom)}</p><p>หลังซื้อ ส่งคำขอถึง ${s.name} เพื่อรับขอบเขต ราคา และระยะเวลาแยกต่างหาก การส่งคำขอยังไม่ใช่การยืนยันจ้าง</p><h3>การตรวจสอบและสิทธิ์ใช้งาน</h3><p>ตัวอย่างเกณฑ์: ทดสอบการกรอกข้อมูลและสูตรพื้นฐาน · สิทธิ์ใช้ส่วนบุคคล/ภายในกิจการเดียว ไม่รวมขายต่อ</p><small>Prototype ยังไม่ได้รับรองสินค้าเชิงพาณิชย์</small></div></div>`);}
function preview(id){const p=product(id);modal(`<h2 id="modal-title">ลองก่อนเลือก · ${esc(p.title)}</h2><p class="muted">ตัวอย่างย่อเพื่อสาธิตประสบการณ์ ไม่ใช่ไฟล์สินค้าฉบับเต็ม</p>${p.style==='sheet'?`<div class="form-grid"><label class="field">ราคาขาย / งบต่อหน่วย (บาท)<input id="calc-price" type="number" min="0" value="100"></label><label class="field">ต้นทุน / ค่าใช้จ่ายต่อหน่วย (บาท)<input id="calc-cost" type="number" min="0" value="60"></label></div><div class="panel"><small>ส่วนต่างต่อหน่วย (ตัวอย่าง)</small><h2 id="calc-result">฿40</h2><p>ตัวอย่างเครื่องคิดเลขสำหรับดูการตอบสนองของเครื่องมือ</p></div>`:p.style==='prompt'?`<label class="field">ธุรกิจหรือประเภทงานของคุณ<input id="prompt-topic" placeholder="เช่น ร้านกาแฟย่านมหาวิทยาลัย" maxlength="120"></label><button class="btn" data-action="generate-prompt">สร้างตัวอย่าง Prompt ↗</button><div class="request-body" id="prompt-output" style="margin-top:16px">กรอกหัวข้อด้านบนเพื่อประกอบคำสั่งตัวอย่าง — ไม่ได้เรียก AI จริง</div>`:`<div class="panel"><h3>My week, with intention.</h3>${['เลือกเป้าหมายสำคัญ 1 เรื่อง','แบ่งงานออกเป็นขั้นตอนเล็ก ๆ','กันเวลาสำหรับตัวเอง'].map(t=>`<label class="checkbox"><input type="checkbox">${t}</label>`).join('')}<label class="field">บันทึกของคุณ<textarea placeholder="ลองเขียนแผนสำหรับสัปดาห์นี้"></textarea></label></div>`}<button class="btn light" data-action="detail" data-id="${id}">← กลับไปดูสินค้า</button>`);}
function checkout(id){if(owns(id)){go('library');return;}const p=product(id);modal(`<h2 id="modal-title">พร้อมเริ่มต้นสิ่งที่ง่ายขึ้น</h2><p class="muted">สรุปคำสั่งซื้อจำลอง</p><div class="checkout-line"><span>${esc(p.title)}<br><small>โดย ${seller(p.seller).name}</small></span><b>${money(p.price)}</b></div><div class="checkout-line"><span>รวมทั้งหมด</span><b>${money(p.price)}</b></div><div class="note">นี่คือการทดลองซื้อ ไม่ขอข้อมูลบัตร ไม่หักเงินจริง และจะได้รับไฟล์สาธิตเท่านั้น</div><form id="checkout-form" data-id="${id}"><label class="checkbox"><input type="checkbox" required>ฉันเข้าใจว่านี่คือการซื้อจำลองและไฟล์ตัวอย่าง</label><button class="btn full" type="submit">ยืนยันการซื้อจำลอง · ${money(p.price)}</button></form>`);}
function library(){return `<div class="page-top"><div class="eyebrow">YOUR PERSONAL TOOLBOX</div><h1>สิ่งดี ๆ ที่คุณเลือกไว้</h1><p>เข้าถึงเครื่องมือ ดาวน์โหลดตัวอย่าง และคุยกับผู้สร้างเพื่อปรับให้ตรงงาน</p></div>${state.owned.length?state.owned.map(o=>{const p=product(o.productId);if(!p)return '';return `<article class="panel library-card">${cover(p,false)}<div><span class="badge">ซื้อแล้ว · DEMO</span><h3 style="margin-top:10px">${esc(p.title)}</h3><p>${esc(p.thai)}</p><small>โดย ${seller(p.seller).name} · ${esc(o.orderId)}</small><div><button class="help-link" data-action="review" data-id="${p.id}">${state.reviews[p.id]?'แก้ไขรีวิวของคุณ':'เขียนรีวิวตัวอย่าง'}</button></div></div><div class="actions"><button class="btn" data-action="custom" data-id="${p.id}">ขอปรับแต่งกับผู้ขาย ↗</button><button class="btn light" data-action="download" data-id="${p.id}">ดาวน์โหลดไฟล์สาธิต ↧</button><button class="help-link" data-action="detail" data-id="${p.id}">รายละเอียดและวิธีใช้</button></div></article>`;}).join(''):empty('กล่องเครื่องมือของคุณยังว่าง','ลองซื้อสินค้าแบบจำลอง แล้วกลับมาส่งคำขอปรับแต่งได้ที่นี่')}<div class="note">ไฟล์ดาวน์โหลดเป็น HTML ตัวอย่างที่เปิดในเบราว์เซอร์ ไม่ใช่ Excel / Notion / PDF ฉบับเต็มตามรายการสินค้า</div>`;}
function custom(id){if(!owns(id)){toast('ซื้อสินค้าแบบจำลองก่อน เพื่อขอปรับแต่งกับผู้ขายเดิม');detail(id);return;}const p=product(id);modal(`<div class="eyebrow">A GOOD TOOL. MODIFIED BY YOU.</div><h2 id="modal-title">บอกผู้สร้างว่าคุณต้องการอะไร</h2><p class="muted">${esc(p.title)} → ${seller(p.seller).name}</p><form id="custom-form" data-id="${id}"><label class="field">หัวข้อคำขอ *<input name="title" required minlength="5" maxlength="100" placeholder="เช่น เพิ่ม Dashboard แยกยอดขาย 2 สาขา"></label><label class="field">รายละเอียดและผลลัพธ์ที่ต้องการ *<textarea name="brief" required minlength="15" maxlength="2500" placeholder="ตอนนี้ใช้งานอย่างไร? อยากเพิ่มหรือเปลี่ยนอะไร? และจะใช้กับใครบ้าง?"></textarea></label><div class="form-grid"><label class="field">งบประมาณสูงสุด (บาท) *<input name="budget" type="number" required min="100" max="1000000" step="1" placeholder="2000"></label><label class="field">วันที่อยากได้รับงาน *<input name="deadline" type="date" min="${localDate()}" required></label></div><label class="field">รูปแบบที่อยากได้<select name="format">${['Excel','Google Sheets','Notion','PDF','Prompt','ให้ผู้ขายแนะนำ'].map(f=>`<option ${f===p.format?'selected':''}>${f}</option>`).join('')}</select></label><div class="note">ส่งตรงถึงผู้ขายของสินค้าที่คุณซื้อในเดโมนี้ ผู้ขายจะเสนอราคาให้พิจารณาก่อน ไม่มีการส่งข้อความจริง</div><button class="btn full" type="submit">ส่งคำขอถึง ${seller(p.seller).name} ↗</button></form>`);}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const STATUS={pending:'รอผู้ขายเสนอราคา',quoted:'ได้รับข้อเสนอแล้ว',working:'กำลังปรับแต่ง',delivered:'ส่งมอบแล้ว',completed:'เสร็จสมบูรณ์',declined:'ปฏิเสธข้อเสนอ',cancelled:'ยกเลิกคำขอ'};
function requestCard(r,asSeller=false){const p=product(r.productId);const steps=['pending','quoted','working','delivered','completed'];const idx=steps.indexOf(r.status);return `<article class="panel request-card"><div class="request-head"><div><small>${esc(r.id)} · ${esc(p?.title||'สินค้า')}</small><h3>${esc(r.title)}</h3></div><span class="badge">${STATUS[r.status]}</span></div><small>ผู้ซื้อ: Nuea (บัญชีตัวอย่าง) → ผู้ขาย: ${seller(r.sellerId).name}</small><div class="request-meta"><span>งบสูงสุด <b>${money(r.budget)}</b></span><span>กำหนดส่ง <b>${esc(r.deadline)}</b></span><span>รูปแบบ <b>${esc(r.format)}</b></span></div><div class="request-body">${esc(r.brief)}</div><div class="timeline">${steps.map((s,i)=>`<span class="${idx>=i?'done':''}">${idx>=i?'●':'○'} ${['ส่งบรีฟ','รับข้อเสนอ','เริ่มงาน','ส่งมอบ','ยืนยันรับงาน'][i]}</span>`).join('<span>→</span>')}</div>${r.quote?`<div class="quote"><div class="request-head"><strong>ข้อเสนอ ${money(r.quote.price)}</strong><small>ระยะเวลา ${r.quote.days} วัน หลังตอบรับ</small></div><p>${esc(r.quote.scope)}</p><small>รวมแก้ไข ${r.quote.revisions} รอบ · ${esc(r.format)}</small></div>`:''}${r.delivery?`<div class="quote"><strong>บันทึกส่งมอบจากผู้ขาย</strong><p>${esc(r.delivery)}</p><button class="text-link" data-action="delivery-download" data-id="${r.id}">ดาวน์โหลดใบส่งมอบตัวอย่าง ↧</button></div>`:''}<div class="actions">${asSeller?(r.status==='pending'?`<button class="btn" data-action="quote" data-id="${r.id}">ส่งข้อเสนอราคา ↗</button>`:r.status==='working'?`<button class="btn" data-action="deliver" data-id="${r.id}">ส่งมอบงานจำลอง ↗</button>`:''):(r.status==='pending'?`<button class="btn light" data-action="cancel-request" data-id="${r.id}">ยกเลิกคำขอ</button>`:r.status==='quoted'?`<button class="btn" data-action="accept" data-id="${r.id}">ตอบรับข้อเสนอจำลอง ↗</button><button class="btn light" data-action="decline" data-id="${r.id}">ปฏิเสธข้อเสนอ</button>`:r.status==='delivered'?`<button class="btn" data-action="complete" data-id="${r.id}">ยืนยันรับงาน</button>`:'')}<button class="btn light" data-action="export-request" data-id="${r.id}">ส่งออกบรีฟ .txt ↧</button></div></article>`;}
function requests(){return `<div class="page-top"><div class="eyebrow">MODIFIED BY YOU</div><h1>คำขอปรับแต่งของคุณ</h1><p>ติดตามตั้งแต่บรีฟแรก จนได้เครื่องมือในแบบที่ต้องการ</p><div class="actions"><button class="btn" data-action="custom-start">+ คำขอใหม่</button><a class="btn light" href="#studio">สลับไปทดลองฝั่งผู้ขาย ↗</a></div></div>${state.requests.length?[...state.requests].reverse().map(r=>requestCard(r)).join(''):empty('ยังไม่มีคำขอปรับแต่ง','เริ่มจากสินค้าที่ซื้อ แล้วส่งรายละเอียดถึงผู้ขายโดยตรง','เลือกสินค้าที่ซื้อ','library')}`;}
function studio(){const rs=state.requests.filter(r=>r.sellerId===studioSeller);const ps=allProducts().filter(p=>p.seller===studioSeller);const s=seller(studioSeller);return `<div class="page-top"><div class="eyebrow">CREATOR WORKSPACE / DEMO</div><h1>Good work starts here.</h1><p>จัดการสินค้าของคุณ และเปลี่ยนคำขอจากผู้ซื้อเป็นงานที่ตรงใจ</p><label class="field" style="max-width:300px">ทดลองมุมมองผู้ขาย<select id="studio-seller">${Object.entries(SELLERS).map(([id,s])=>`<option value="${id}" ${id===studioSeller?'selected':''}>${s.name}</option>`).join('')}</select></label></div><div class="metrics"><div class="panel"><span>สินค้าของผู้ขายนี้</span><strong>${ps.length}</strong></div><div class="panel"><span>คำขอรอตอบ</span><strong>${rs.filter(r=>r.status==='pending').length}</strong></div><div class="panel"><span>งานที่กำลังทำ</span><strong>${rs.filter(r=>r.status==='working').length}</strong></div></div><div class="studio-tabs"><button class="chip ${studioTab==='requests'?'active':''}" data-action="studio-tab" data-id="requests">คำขอจากลูกค้า (${rs.length})</button><button class="chip ${studioTab==='products'?'active':''}" data-action="studio-tab" data-id="products">สินค้าของฉัน</button><button class="btn small" data-action="new-product">+ เพิ่มสินค้าเดโม</button></div>${studioTab==='requests'?(rs.length?[...rs].reverse().map(r=>requestCard(r,true)).join(''):empty('ยังไม่มีคำขอถึง '+s.name,'ทดลองซื้อสินค้าของผู้ขายนี้ แล้วส่งคำขอจากหน้าสินค้าของฉัน')):`<div class="grid" style="margin-bottom:40px">${ps.map(card).join('')}</div>`}<div class="note">การสลับผู้ขายใช้เพื่อสาธิตเท่านั้น ระบบจริงต้องมีบัญชีผู้ใช้ การตรวจสิทธิ์ และฐานข้อมูลแยกจากเบราว์เซอร์</div>`;}
function quote(id){const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='pending')return;modal(`<h2 id="modal-title">เสนอราคาสำหรับคำขอนี้</h2><p>${esc(r.title)}</p><form id="quote-form" data-id="${id}"><div class="form-grid"><label class="field">ราคาเสนอ (บาท) *<input name="price" type="number" min="1" max="1000000" step="1" required value="${r.budget}"></label><label class="field">ระยะเวลาหลังตอบรับ (วัน) *<input name="days" type="number" min="1" max="365" step="1" required value="7"></label></div><label class="field">ขอบเขตงานและสิ่งที่จะส่งมอบ *<textarea name="scope" minlength="10" maxlength="2500" required placeholder="ระบุฟังก์ชันที่จะเพิ่ม สิ่งที่ไม่รวม และไฟล์ที่จะส่งมอบ"></textarea></label><label class="field">จำนวนรอบแก้ไข<input name="revisions" type="number" min="0" max="20" step="1" value="2" required></label><button class="btn full" type="submit">ส่งข้อเสนอจำลองให้ผู้ซื้อ ↗</button></form>`);}
function sellerProfile(id){const s=seller(id);modal(`<div class="seller-row"><span class="avatar">${s.initials}</span><div><h2 id="modal-title">${s.name}</h2><p>${s.specialty}</p></div></div><p>${s.bio}</p><div class="note">โปรไฟล์ผู้ขายสมมติ · ส่งคำขอปรับแต่งได้จากสินค้าที่ซื้อแล้ว</div><div class="compact-grid">${allProducts().filter(p=>p.seller===id).map(card).join('')}</div>`);}
function newProduct(){modal(`<h2 id="modal-title">เพิ่มสินค้าในร้านตัวอย่าง</h2><p class="muted">ผู้ขาย ${seller(studioSeller).name} · บันทึกเฉพาะในเบราว์เซอร์นี้</p><form id="product-form"><label class="field">ชื่อสินค้า *<input name="title" required minlength="3" maxlength="70"></label><label class="field">คำอธิบายสั้น *<input name="desc" required minlength="10" maxlength="160"></label><div class="form-grid"><label class="field">ราคา (บาท) *<input name="price" type="number" min="1" max="1000000" step="1" required></label><label class="field">หมวดหมู่<select name="category">${CATEGORIES.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label></div><label class="field">ประเภทสินค้า<select name="format">${['Excel','Google Sheets','Notion','PDF','Prompt'].map(f=>`<option>${f}</option>`).join('')}</select></label><label class="field">สิ่งที่จะได้รับ *<textarea name="includes" required minlength="5" maxlength="1000" placeholder="หนึ่งรายการต่อบรรทัด"></textarea></label><div class="note">สร้างรายการสาธิต ไม่มีการอัปโหลดไฟล์เชิงพาณิชย์จริง สินค้าจะมีหน้าตัวอย่างอัตโนมัติ</div><button class="btn full" type="submit">เพิ่มสินค้าตัวอย่าง ↗</button></form>`);}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function sampleDownload(id){if(!owns(id))return;const p=product(id);const body=`<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)} — Demo</title><style>body{font:16px/1.8 system-ui;max-width:850px;margin:40px auto;padding:24px;color:#222}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:12px}th{background:#222;color:white}small{color:#777}</style><h1>MODU / ${esc(p.title)}</h1><p>ไฟล์สาธิตเท่านั้น — ไม่ใช่สินค้าฉบับเต็ม</p><p>${esc(p.desc)}</p><h2>สิ่งที่จะมีในสินค้าจริงตามตัวอย่าง</h2><ul>${p.includes.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><h2>แบบฝึกเริ่มต้น</h2><table><tr><th>งานที่ต้องทำ</th><th>วันที่</th><th>บันทึก</th></tr><tr><td contenteditable>กำหนดเป้าหมาย</td><td contenteditable>วันจันทร์</td><td contenteditable>คลิกเพื่อแก้ข้อความ</td></tr><tr><td contenteditable>กรอกข้อมูลตัวอย่าง</td><td contenteditable>วันอังคาร</td><td contenteditable>ทดลองใช้เครื่องมือ</td></tr></table><p>ตารางนี้แก้ไขบนหน้าจอได้ แต่ไม่มีการบันทึกอัตโนมัติ ใช้ Print → Save as PDF เพื่อเก็บสำเนา</p><small>สร้างจาก MODU interactive prototype · ไม่มีการเชื่อมต่อบัญชีหรือบริการภายนอก</small></html>`;download(p.id+'-demo.html',body,'text/html;charset=utf-8');toast('ดาวน์โหลด HTML สาธิตแล้ว');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='detail')detail(id);else if(a==='preview')preview(id);else if(a==='seller')sellerProfile(id);else if(a==='checkout')checkout(id);else if(a==='custom')custom(id);else if(a==='download')sampleDownload(id);
  else if(a==='save'){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];persist();b.classList.toggle('saved',state.wishlist.includes(id));b.textContent=state.wishlist.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',state.wishlist.includes(id));if(filters.saved&&$('#product-grid'))renderGrid();}
  else if(a==='category'){filters.category=id;renderGrid();}else if(a==='clear'){filters={category:'ทั้งหมด',query:'',sort:'featured',format:'ทั้งหมด',price:'all',saved:false};if($('#product-grid')){$('#search-input').value='';$('#format').value='ทั้งหมด';renderGrid();}else go('market');}
  else if(a==='search'){filters.query=b.dataset.query;$('#search-input').value=filters.query;renderGrid();$('#catalog').scrollIntoView();}
  else if(['market','library','requests','studio'].includes(a))go(a);
  else if(a==='custom-start'){if(!state.owned.length){modal(`<h2 id="modal-title">เริ่มจากเครื่องมือที่ใช่</h2><p>ซื้อสินค้าแบบจำลองก่อน แล้วส่งคำขอถึงผู้สร้างของสินค้านั้นได้ทันที</p><button class="btn" data-action="detail" data-id="cost">ลอง Small Shop Finance Kit ↗</button>`);}else{modal(`<h2 id="modal-title">เลือกสินค้าที่ต้องการปรับแต่ง</h2><div class="actions">${state.owned.map(o=>product(o.productId)).filter(Boolean).map(p=>`<button class="btn light" data-action="custom" data-id="${p.id}">${esc(p.title)} ↗</button>`).join('')}</div>`);}}
  else if(a==='how')modal(`<h2 id="modal-title">ลองใช้ MODU ใน 4 ขั้นตอน</h2><ol><li>เลือกสินค้า เปิดรายละเอียดและตัวอย่าง</li><li>กดซื้อจำลอง แล้วไปที่ “สินค้าของฉัน”</li><li>ส่งคำขอปรับแต่ง ระบุบรีฟ งบ และวันส่ง</li><li>เปิด Seller studio เลือกผู้ขายที่ตรงกัน แล้วเสนอราคา</li></ol><p>กลับมาที่คำขอปรับแต่งเพื่อตอบรับ จากนั้นผู้ขายส่งมอบ และผู้ซื้อยืนยันรับงานได้</p><div class="note">ทุกขั้นตอนเป็นการสาธิตในเครื่องเดียว ไม่มีการส่งคำขอหรือชำระเงินจริง</div>`);
  else if(a==='studio-tab'){studioTab=id;render();}else if(a==='new-product')newProduct();else if(a==='quote')quote(id);
  else if(a==='accept'){const r=state.requests.find(r=>r.id===id);if(r?.status!=='quoted')return;modal(`<h2 id="modal-title">ยืนยันข้อเสนอจำลอง</h2><p>${esc(r.title)}</p><div class="checkout-line"><span>ราคาเพิ่มเติมสำหรับปรับแต่ง</span><b>${money(r.quote.price)}</b></div><p>ระยะเวลา ${r.quote.days} วันหลังตอบรับ · แก้ไข ${r.quote.revisions} รอบ</p><div class="request-body">${esc(r.quote.scope)}</div><div class="note">การตอบรับในเดโมไม่เกิดการจ้างหรือชำระเงินจริง</div><button class="btn full" data-action="confirm-accept" data-id="${id}">ยืนยันและเริ่มงานจำลอง</button>`);}
  else if(a==='confirm-accept'){const r=state.requests.find(r=>r.id===id);if(r?.status==='quoted'){r.status='working';persist();closeModal();render();toast('ตอบรับแล้ว · ทดลองส่งมอบต่อได้ที่ Seller studio');}}
  else if(['decline','cancel-request','complete'].includes(a)){const r=state.requests.find(r=>r.id===id);if(!r)return;const expected={decline:'quoted','cancel-request':'pending',complete:'delivered'};if(r.status!==expected[a])return;r.status={decline:'declined','cancel-request':'cancelled',complete:'completed'}[a];persist();render();toast('อัปเดตสถานะแล้ว');}
  else if(a==='deliver'){const r=state.requests.find(r=>r.id===id);if(r?.status!=='working')return;modal(`<h2 id="modal-title">ส่งมอบงานจำลอง</h2><p>${esc(r.title)}</p><form id="delivery-form" data-id="${id}"><label class="field">สรุปงานที่ปรับและวิธีใช้งาน *<textarea name="delivery" required minlength="10" maxlength="2500" placeholder="ระบุสิ่งที่เพิ่ม การตรวจสอบ และขั้นตอนเริ่มใช้"></textarea></label><div class="note">เดโมจะสร้างใบส่งมอบ .txt ไม่ใช่ไฟล์งานที่ปรับแต่งจริง</div><button class="btn full" type="submit">ส่งมอบให้ผู้ซื้อจำลอง ↗</button></form>`);}
  else if(a==='export-request'){const r=state.requests.find(r=>r.id===id);download(r.id+'-brief.txt',`MODU — DEMO REQUEST\n${r.id}\nสินค้า: ${product(r.productId).title}\nถึง: ${seller(r.sellerId).name}\nหัวข้อ: ${r.title}\nรายละเอียด: ${r.brief}\nงบ: ${r.budget} THB\nวันที่ต้องการ: ${r.deadline}\nรูปแบบ: ${r.format}\nสถานะ: ${STATUS[r.status]}\n`);}
  else if(a==='delivery-download'){const r=state.requests.find(r=>r.id===id);if(r?.delivery)download(r.id+'-delivery-demo.txt',`MODU — ใบส่งมอบสาธิต (ไม่ใช่ไฟล์สินค้าจริง)\n${r.title}\nผู้ขาย: ${seller(r.sellerId).name}\n\n${r.delivery}`);}
  else if(a==='generate-prompt'){const topic=$('#prompt-topic').value.trim();$('#prompt-output').textContent=topic?`ช่วยวางแผนคอนเทนต์ 7 วันสำหรับ ${topic} โดยถามกลุ่มเป้าหมายและเป้าหมายธุรกิจก่อน จากนั้นจัดเป็นตาราง วัน / หัวข้อ / รูปแบบ / ข้อความหลัก / สิ่งที่ต้องตรวจสอบ หลีกเลี่ยงการแต่งข้อเท็จจริง และระบุสมมติฐานให้ชัดเจน`:'กรุณาใส่ธุรกิจหรือประเภทงานก่อน';}
  else if(a==='review'){if(!owns(id))return;const r=state.reviews[id]||{};modal(`<h2 id="modal-title">รีวิวสินค้าตัวอย่าง</h2><form id="review-form" data-id="${id}"><label class="field">คะแนน<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${r.rating==n?'selected':''}>${n} ดาว</option>`).join('')}</select></label><label class="field">ประสบการณ์ใช้งาน<textarea name="text" required minlength="5" maxlength="1000">${esc(r.text||'')}</textarea></label><div class="note">รีวิวเก็บในเบราว์เซอร์นี้ ไม่ได้เผยแพร่ต่อสาธารณะหรือรวมกับคะแนนตัวอย่าง</div><button class="btn" type="submit">บันทึกรีวิว</button></form>`);}
});
document.addEventListener('submit',e=>{const f=e.target;if(!['search-form','checkout-form','custom-form','quote-form','delivery-form','product-form','review-form'].includes(f.id))return;e.preventDefault();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f)),id=f.dataset.id;
  if(f.id==='search-form'){filters.query=$('#search-input').value.trim();renderGrid();$('#catalog').scrollIntoView();return;}
  if(f.id==='checkout-form'){if(!owns(id))state.owned.push({productId:id,orderId:uid('ORDER'),date:new Date().toISOString()});persist();modal(`<div class="center"><div class="success-mark">✓</div><h2 id="modal-title">เครื่องมือใหม่ พร้อมให้ลองแล้ว</h2><p>เพิ่ม ${esc(product(id).title)} ในสินค้าของฉันแล้ว</p><div class="actions" style="justify-content:center"><button class="btn" data-action="custom" data-id="${id}">ขอปรับแต่งกับผู้ขาย ↗</button><button class="btn light" data-action="library">ไปที่สินค้าของฉัน</button></div></div>`);return;}
  if(f.id==='custom-form'){if(!owns(id))return;if(d.deadline<localDate()){toast('กรุณาเลือกวันที่ตั้งแต่วันนี้เป็นต้นไป');return;}if(d.title.trim().length<5||d.brief.trim().length<15){toast('กรุณาระบุหัวข้อและรายละเอียดให้ครบ');return;}state.requests.push({id:uid('REQ'),productId:id,sellerId:product(id).seller,title:d.title.trim(),brief:d.brief.trim(),budget:Number(d.budget),deadline:d.deadline,format:d.format,status:'pending',createdAt:new Date().toISOString()});studioSeller=product(id).seller;persist();go('requests');toast('ส่งคำขอจำลองแล้ว · ทดลองตอบจาก Seller studio ได้');return;}
  if(f.id==='quote-form'){const r=state.requests.find(r=>r.id===id);if(r?.status!=='pending')return;if(d.scope.trim().length<10){toast('กรุณาระบุขอบเขตงานให้ชัดเจน');return;}r.quote={price:Number(d.price),days:Number(d.days),revisions:Number(d.revisions),scope:d.scope.trim()};r.status='quoted';}
  if(f.id==='delivery-form'){const r=state.requests.find(r=>r.id===id);if(r?.status!=='working')return;if(d.delivery.trim().length<10){toast('กรุณาระบุรายละเอียดการส่งมอบ');return;}r.delivery=d.delivery.trim();r.status='delivered';}
  if(f.id==='product-form'){if(d.title.trim().length<3||d.desc.trim().length<10||!d.includes.trim()){toast('กรุณาระบุข้อมูลสินค้าให้ครบ');return;}state.listings.push({id:uid('custom-product'),title:d.title.trim(),thai:d.desc.trim(),desc:d.desc.trim(),category:d.category,format:d.format,price:Number(d.price),seller:studioSeller,rating:'ใหม่',reviews:0,style:d.format==='Prompt'?'prompt':['PDF','Notion'].includes(d.format)?'planner':'sheet',tone:d.format==='Prompt'?'dark':'soft',tag:'NEW / DEMO',preview:d.title.trim(),includes:d.includes.split('\n').map(s=>s.trim()).filter(Boolean),compat:'รายการสาธิต · ต้องตรวจสอบไฟล์จริงก่อนเปิดขาย',custom:'ส่งคำขอปรับแต่งกับผู้ขายหลังซื้อจำลอง'});studioTab='products';}
  if(f.id==='review-form'){if(!owns(id))return;state.reviews[id]={rating:Number(d.rating),text:d.text.trim()};}
  persist();closeModal();render();toast('บันทึกข้อมูลตัวอย่างแล้ว');
});
document.addEventListener('change',e=>{if(e.target.id==='sort'){filters.sort=e.target.value;renderGrid();}if(e.target.id==='format'){filters.format=e.target.value;renderGrid();}if(e.target.id==='price-filter'){filters.price=e.target.value;renderGrid();}if(e.target.id==='studio-seller'){studioSeller=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='calc-price'||e.target.id==='calc-cost')$('#calc-result').textContent=money(Number($('#calc-price').value)-Number($('#calc-cost').value));});
$('#wishlist').addEventListener('click',()=>{filters.saved=!filters.saved;go('market');setTimeout(()=>$('#catalog')?.scrollIntoView(),40);});
$('#modal .close').addEventListener('click',closeModal);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#reset').addEventListener('click',()=>{modal(`<h2 id="modal-title">เริ่มทดลองใหม่?</h2><p>ล้างคำสั่งซื้อ คำขอ รีวิว สินค้าที่เพิ่ม และรายการที่บันทึกเฉพาะเดโมนี้</p><button class="btn" id="confirm-reset">ยืนยันรีเซ็ตเดโม</button>`);$('#confirm-reset').onclick=()=>{state=EMPTY_STATE();filters={category:'ทั้งหมด',query:'',sort:'featured',format:'ทั้งหมด',price:'all',saved:false};persist();go('market');toast('เริ่มเดโมใหม่แล้ว');};});
window.addEventListener('hashchange',render);render();
